{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "male"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "code": {
          "text": "Right helix nodular lesion, likely chondrodermatitis nodularis helicis; non-melanoma skin cancer requires exclusion"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "code": {
          "text": "Sleep disturbance with maintenance insomnia secondary to painful right ear lesion; not primary insomnia"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Systolic blood pressure"
            },
            "valueQuantity": {
              "value": 136,
              "unit": "mmHg"
            }
          },
          {
            "code": {
              "text": "Diastolic blood pressure"
            },
            "valueQuantity": {
              "value": 78,
              "unit": "mmHg"
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Heart rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 72,
          "unit": "beats/min"
        },
        "note": [
          {
            "text": "Regular."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Temperature"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Oxygen saturation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 98,
          "unit": "%"
        },
        "note": [
          {
            "text": "On room air."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Body mass index"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 27,
          "unit": "kg/m2"
        },
        "note": [
          {
            "text": "Approximate estimate."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Right ear pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Sharp pain at night when lying on the right side, described as like someone jabbing a match in the ear; settles when he turns over or rubs it and recurs when he lies on it again. Ongoing approximately 3–4 months and getting worse."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Sleep"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports approximately 4–5 hours of broken sleep and repeated waking due to right ear pain. No difficulty getting to sleep. Denies low mood, racing thoughts, and early waking independent of the ear pain."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Right upper ear lump"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Small painful lump on the upper right ear, present for approximately 6 months; worse with pressure from the pillow and sometimes crusty. No discharge or bleeding other than cracking."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Right ear associated symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies hearing loss, tinnitus, vertigo, and fevers."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Sun exposure and skin cancer history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports heavy lifetime sun exposure, including years of driving with the window down and frequent ear sunburn. No known past skin cancer."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Right helix and upper antihelix examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Approximately 6–7 mm firm, tender, dome-shaped nodule with superficial central erosion and slight scale/crust, mild surrounding erythema, and very focal tenderness to light pressure. No fluctuation or warmth. No obvious rolled edge or pearly lesion, though crust partly obscures the lesion."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Pre-auricular and post-auricular lymph nodes"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No pre-auricular or post-auricular nodes."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Ear canals and tympanic membranes"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Canals and tympanic membranes normal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Brief skin inspection"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Brief inspection of face, scalp, and dorsal hands found no obvious other suspicious lesions; this was not a full skin check."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Betamethasone valerate 0.02% cream"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Apply thinly to the lesion once daily for up to 2 weeks, then stop; for inflammation only, not definitive treatment.",
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d",
                "boundsDuration": {
                  "value": 2,
                  "unit": "weeks",
                  "code": "wk",
                  "system": "http://unitsofmeasure.org"
                }
              }
            },
            "route": {
              "text": "Topical"
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-2",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-2",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "For nocturnal pain, up to four times daily as needed; maximum 4 g in 24 hours.",
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
            ],
            "maxDosePerPeriod": {
              "numerator": {
                "value": 4,
                "unit": "g"
              },
              "denominator": {
                "value": 24,
                "unit": "h"
              }
            }
          }
        ]
      }
    }
  ]
}
